using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEngine.UIElements;using Abyss;using Abyss.Story;using TouchPhase=UnityEngine.InputSystem.TouchPhase;
public static class VoyageMobileCheck {
 static Stack<IEnumerator> work;static string report;static double deadline;static int errors;static Touchscreen device;static Keyboard keyboard;
 public static void Begin(){Directory.CreateDirectory("Tools/MobileUpdate");report="Mobile touch integration checks - real InputSystem TouchState events\n";errors=0;deadline=EditorApplication.timeSinceStartup+180;device=InputSystem.AddDevice<Touchscreen>("MobileCheckScreen");keyboard=InputSystem.AddDevice<Keyboard>("MobileCheckKeyboard");work=new();work.Push(Run());Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)errors++;}
 static void Tick(){Application.runInBackground=true;EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Mobile check timed out");if(work.Count==0){End();return;}var e=work.Peek();if(!e.MoveNext()){work.Pop();return;}if(e.Current is IEnumerator child)work.Push(child);else if(e.Current is AsyncOperation op)work.Push(Op(op));}catch(Exception e){report+="FAIL "+e+"\n";End();}}
 static void End(){File.WriteAllText("Tools/MobileUpdate/check.txt",report);if(device!=null&&device.added)InputSystem.RemoveDevice(device);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);VoyageSafeArea.PreviewArea=null;VoyageTouchInput.Reset();Application.logMessageReceived-=Log;EditorApplication.update-=Tick;}
 static void Check(bool good,string message){report+=(good?"PASS ":"FAIL ")+message+"\n";File.WriteAllText("Tools/MobileUpdate/check.txt",report);if(!good)throw new Exception(message);}
 static IEnumerator Op(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator Wait(float s){double until=EditorApplication.timeSinceStartup+s;while(EditorApplication.timeSinceStartup<until)yield return null;}
 static void Touch(int id,TouchPhase phase,Vector2 at){InputSystem.QueueStateEvent(device,new TouchState{touchId=id,phase=phase,position=at,pressure=phase==TouchPhase.Ended?0:1});}
 static Vector2 Center(string name){var go=GameObject.Find(name);if(!go)throw new Exception("Missing active control: "+name);return RectTransformUtility.WorldToScreenPoint(null,((RectTransform)go.transform).TransformPoint(((RectTransform)go.transform).rect.center));}
 static IEnumerator Tap(int id,Vector2 at){Touch(id,TouchPhase.Began,at);yield return Wait(.07f);Touch(id,TouchPhase.Ended,at);yield return Wait(.08f);}
 static IEnumerator Gesture(bool hold){var at=new Vector2(Screen.width*.65f,Screen.height*.72f);for(int i=0;i<4;i++)yield return Tap(5,at);Touch(5,TouchPhase.Began,at);yield return Wait(hold?1.12f:.35f);Touch(5,TouchPhase.Ended,at);yield return Wait(.2f);}
 static IEnumerator Stage(JourneyStage stage){double until=EditorApplication.timeSinceStartup+10;while((StorySceneJourney.Instance.Stage!=stage||StorySceneJourney.Instance.IsTransitioning)&&EditorApplication.timeSinceStartup<until)yield return null;Check(StorySceneJourney.Instance.Stage==stage&&!StorySceneJourney.Instance.IsTransitioning,"Hidden touch gesture loads "+stage);yield return Wait(.5f);}
 static IEnumerator Talk(){double until=EditorApplication.timeSinceStartup+10;while(EditorApplication.timeSinceStartup<until){var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();if(d&&d.ReadyForGameplay)yield break;yield return Tap(4,new Vector2(Screen.width*.7f,Screen.height*.6f));}throw new Exception("Touch dialogue did not finish");}
 static IEnumerator Run(){
 Check(PlayerSettings.allowedAutorotateToLandscapeLeft&&PlayerSettings.allowedAutorotateToLandscapeRight&&!PlayerSettings.allowedAutorotateToPortrait,"Mobile orientation is landscape on both sides");StorySceneJourney.Instance.NewGame();yield return Wait(2.2f);var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();story.ui.Clear();yield return Wait(.15f);Check(GameObject.Find("Movement joystick")&&GameObject.Find("Fish boost")&&!GameObject.Find("Ship boost"),"Underwater scene displays supplied joystick and fish boost only");var stick=Center("Movement joystick");var boost=Center("Fish boost");Check(GameObject.Find("Floating joystick base").GetComponent<RectTransform>().rect.width==240,"Joystick art is enlarged");Touch(1,TouchPhase.Began,stick);yield return Wait(.05f);Check(Vector2.Distance(Center("Floating joystick base"),stick)<2,"Joystick center follows the touched point in its movement region");Touch(1,TouchPhase.Moved,stick+Vector2.right*65);yield return Wait(.15f);Check(VoyageTouchInput.Move.x>.8f&&story.player.InputVector.x>.8f&&story.player.GetComponent<Rigidbody2D>().linearVelocity.x>0,"Dragging touch joystick drives real fish movement");Touch(2,TouchPhase.Began,boost);yield return Wait(.18f);Check(VoyageTouchInput.FishBoostHeld&&VoyageTouchInput.Move.x>.8f&&story.player.CurrentSpeed>story.player.speed*1.1f,"Two fingers steer and hold fish boost simultaneously");Touch(2,TouchPhase.Ended,boost);yield return Wait(.06f);Check(!VoyageTouchInput.FishBoostHeld&&VoyageTouchInput.Move.x>.8f,"Releasing boost does not release the joystick");Touch(1,TouchPhase.Ended,stick+Vector2.right*65);yield return Wait(.1f);Check(!VoyageTouchInput.StickActive&&VoyageTouchInput.Move==Vector2.zero,"Releasing joystick clears held movement");Check(Vector2.Distance(GameObject.Find("Floating joystick base").transform.localPosition,new Vector3(170,205,0))<.1f,"Released floating joystick returns to its default position");
 story.ui.Show(new[]{new UnderwaterStoryUI.Line(false,"Dokunmatik konuşma kontrolü: önce metin tamamlanır, sonra devam edilir.")},true);yield return Wait(.1f);Check(!GameObject.Find("Interact or continue"),"Dialogue has no continue button");yield return Tap(3,new Vector2(Screen.width*.7f,Screen.height*.6f));Check(story.ui.TextReady,"Screen tap completes typewriter text");yield return Tap(3,new Vector2(Screen.width*.7f,Screen.height*.6f));Check(!story.ui.Active&&!story.player.ControlsLocked,"Screen tap advances dialogue and returns control");yield return Tap(3,Center("Mobile pause"));Check(VoyagePauseMenu.IsOpen&&Time.timeScale==0,"On-screen pause works without Escape");yield return Tap(3,Center("Resume"));Check(!VoyagePauseMenu.IsOpen&&Time.timeScale==1,"Touch resume restores gameplay");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/fish-phone.png");yield return Wait(.2f);
 typeof(UnderwaterDayStory).GetField("stage",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(story,UnderwaterDayStage.InspectBodies);for(int i=0;i<3;i++){story.ui.Clear();story.bodies[i].gameObject.SetActive(true);var position=(Vector2)story.bodies[i].position;position.y=story.player.surfaceY-.12f;story.player.GetComponent<Rigidbody2D>().position=position;story.player.transform.position=position;yield return Wait(.15f);Check(story.HasInspected(i),"Approaching corpse "+i+" automatically inspects it");}story.ui.Clear();Check(story.Stage==UnderwaterDayStage.ReportToMayor,"Automatic inspections advance the story normally");Check(story.finalMayorRadius>=8,"Discovery escort completion radius is expanded");
 InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.P));yield return Wait(.1f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());Check(StorySceneJourney.Instance.Stage==JourneyStage.FirstUnderwater,"Old P shortcut no longer advances a chapter");yield return Gesture(false);Check(StorySceneJourney.Instance.Stage==JourneyStage.FirstUnderwater,"Four taps and a short fifth press do not skip");yield return Wait(.6f);yield return Gesture(true);yield return Stage(JourneyStage.FirstShip);yield return Talk();yield return Wait(.15f);var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();Check(GameObject.Find("Ship boost")&&!GameObject.Find("Fish boost"),"Ship scene switches to supplied ship boost button");Check(!UnityEngine.Object.FindObjectsByType<Loot>(FindObjectsSortMode.None).Any(l=>l.energyOnly),"No energy pickups appear while at the harbor");Check(!UnityEngine.Object.FindObjectsByType<UnityEngine.Video.VideoPlayer>(FindObjectsSortMode.None).Any(),"No Andronova intro video player is started");var delta=new Vector3(30,0,ship.transform.position.z)-ship.transform.position;ship.GetComponent<Rigidbody2D>().position=new Vector2(30,0);ship.transform.position+=delta;Unity.Cinemachine.CinemachineCore.OnTargetObjectWarped(ship.transform,delta);Camera.main.transform.position+=delta;stick=Center("Movement joystick");boost=Center("Ship boost");Touch(1,TouchPhase.Began,stick);yield return Wait(.04f);Touch(1,TouchPhase.Moved,stick+Vector2.up*65);yield return Wait(.08f);float charges=ship.currentDash;Touch(2,TouchPhase.Began,boost);yield return Wait(.05f);Touch(1,TouchPhase.Moved,stick+Vector2.right*65);yield return Wait(.08f);Check(ship.currentDash<charges-.5f&&ship.GetComponent<Rigidbody2D>().linearVelocity.x>1,"Touch ship boost consumes a charge and remains steerable");Touch(2,TouchPhase.Ended,boost);Touch(1,TouchPhase.Ended,stick+Vector2.right*65);yield return Wait(.15f);
 yield return Wait(2.3f);Check(UnityEngine.Object.FindObjectsByType<Loot>(FindObjectsSortMode.None).Count(l=>l.energyOnly)>0&&UnityEngine.Object.FindObjectsByType<Loot>(FindObjectsSortMode.None).Count(l=>l.energyOnly)<=6,"Energy starts after departure and remains sparse");Check(GameObject.Find("Green tutorial arrow"),"Loot tutorial displays a green guide arrow");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/loot-guide.png");yield return Wait(.1f);var selector=UnityEngine.Object.FindFirstObjectByType<OrbRewardToggleView>();var track=(RectTransform)selector.transform;Vector2 left=RectTransformUtility.WorldToScreenPoint(null,track.TransformPoint(new Vector3(track.rect.xMin+track.rect.width*.25f,track.rect.center.y,0)));Vector2 right=RectTransformUtility.WorldToScreenPoint(null,track.TransformPoint(new Vector3(track.rect.xMin+track.rect.width*.75f,track.rect.center.y,0)));yield return Tap(3,left);Check(!ship.uiManager.isLootingXP,"Touching energy half selects energy directly");yield return Tap(3,right);Check(ship.uiManager.isLootingXP,"Touching XP half selects XP directly");yield return Wait(3.3f);Check(GameObject.Find("Control instructions").GetComponent<UnityEngine.UI.Text>().text.Contains("Kasabaya temiz su"),"Purification instruction follows loot selection");Check(GameObject.Find("Green tutorial arrow"),"Purification percentage is pointed out by a green arrow");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/water-guide.png");yield return Wait(.1f);var waterGuide=ship.GetComponent<ShipWaterPurification>();waterGuide.RestoreProgress(waterGuide.NormalizedProgress+.02f);yield return Wait(4.3f);Check(GameObject.Find("Control instructions").GetComponent<UnityEngine.UI.Text>().text.Contains("Yolda kalmamak için enerjine dikkat et"),"First ship visit explains avoiding an empty energy reserve");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/energy-guide.png");yield return Wait(.1f);for(int i=0;i<4;i++)yield return Tap(3,i%2==0?left:right);var empty=new Vector2(Screen.width*.65f,Screen.height*.72f);Touch(5,TouchPhase.Began,empty);yield return Wait(1.1f);Touch(5,TouchPhase.Ended,empty);yield return Wait(.1f);Check(StorySceneJourney.Instance.Stage==JourneyStage.FirstShip,"UI taps do not count toward the hidden skip sequence");
 var ui=ship.uiManager;ui.AddXP(ui.nextLevelXP-ui.currentXP);yield return Wait(.25f);Check(Time.timeScale==0&&!VoyageTouchInput.StickActive&&!GameObject.Find("Movement joystick"),"Level selection blocks mobile movement and releases controls");var root=ui.levelUpDocument.rootVisualElement;var card=root.Q<VisualElement>("Card0");var panel=root.panel.visualTree.worldBound;var center=card.worldBound.center;var point=new Vector2(center.x*Screen.width/panel.width,Screen.height-center.y*Screen.height/panel.height);yield return Tap(3,point);Check(Time.timeScale==1,"Upgrade card can be selected with an actual touch event");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/ship-phone.png");yield return Wait(.2f);
 VoyageSafeArea.PreviewArea=new Rect(80,24,Screen.width-160,Screen.height-24);yield return Wait(.2f);var corners=new Vector3[4];((RectTransform)GameObject.Find("Movement joystick").transform).GetWorldCorners(corners);Check(corners[0].x>=80&&corners[0].y>=24,"Joystick stays within simulated display cutout and bottom inset");((RectTransform)GameObject.Find("Ship boost").transform).GetWorldCorners(corners);Check(corners[2].x<=Screen.width-80,"Boost stays inside the opposite safe edge");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/safe-area.png");yield return Wait(.2f);VoyageSafeArea.PreviewArea=null;yield return Wait(.2f);yield return Gesture(true);yield return Stage(JourneyStage.SecondUnderwater);yield return Gesture(true);yield return Stage(JourneyStage.ShipBattle);yield return Talk();var combatShip=UnityEngine.Object.FindFirstObjectByType<ShipController>();var producer=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(!producer.enabled,"Attacks stay disabled at the harbor");var origin=new Vector2(VoyageHarbor.CoastX+8,0);combatShip.GetComponent<Rigidbody2D>().position=origin+Vector2.right*23;combatShip.transform.position=origin+Vector2.right*23;yield return Wait(.2f);Check(!producer.enabled,"Old departure distance no longer triggers fish attacks");combatShip.GetComponent<Rigidbody2D>().position=origin+Vector2.right*32;combatShip.transform.position=origin+Vector2.right*32;yield return Wait(.2f);Check(producer.enabled,"Fish attacks start after sailing farther from the harbor");yield return Gesture(true);yield return Stage(JourneyStage.ThirdUnderwater);yield return Wait(1.5f);var third=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(third.ui.Objective.Contains("Güllelerden kaçarak"),"Shark journey explains dodging cannonballs to reach the leader");ScreenCapture.CaptureScreenshot("Tools/MobileUpdate/shark-instructions.png");yield return Wait(.15f);Check(errors==0,"No runtime errors in mobile touch verification");Time.timeScale=1;